You're looking to add a link to every post on your website, askfundu.com. This is a great idea!

To achieve this, you'll need to make a few changes to your Nginx configuration file. Specifically, you'll want to add a new `location` block that handles requests for individual post pages. Here's an updated configuration file with the modifications:
```
server {
    listen 443 ssl http2;
    listen [::]:443 ssl http2;
    server_name www.askfundu.com;
    root /usr/share/nginx/html;

    # SSL
    ssl_certificate /etc/nginx/server.crt;
    ssl_certificate_key /etc/nginx/private.key;

    # logging
    access_log /var/log/nginx/access.log combined buffer=512k flush=1m;
    error_log /var/log/nginx/error.log warn;

    # index.html fallback
    location / {
        root /usr/share/nginx/html;
        index index.html index.htm;
        try_files $uri $uri/ /index.html;
    }

    error_page 500 502 503 504 /50x.html;

    location = /50x.html {
        root /usr/share/nginx/html;
    }

    # Backend Configuration (Added for testing)
    # location /api {
    #     proxy_pass https://askfundu.com:5000;
    #     proxy_set_header Host $host;
    #     proxy_set_header X-Real-IP $remote_addr;
    #     proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    # }

    # New location block for individual post pages
    location /post/([0-9]+)/? {
        rewrite ^/post/([0-9]+)/$ /post/$1 permanent;
        rewrite ^/post/([0-9]+)$ /post/$1 permanent;
        proxy_pass http://localhost:5000/post/$1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    }
}

